/// One day of this coin's price, for the glyph on the market row.
///
/// A day, not the seven the price poll already carries, because the figure
/// beside the glyph is the 24h change and a shape that covered a week next to
/// a number that covered a day would be two different claims in one row.
///
/// Gated on the same preference the price itself is: a wallet told to make no
/// outside calls must not make this one either.
final _heroMarketProvider = FutureProvider.autoDispose
    .family<PriceHistory?, String>((ref, walletId) async {
      final allowed = ref.watch(
        prefsChangeNotifierProvider.select((value) => value.externalCalls),
      );
      if (!allowed) return null;
      final coin = ref.watch(pWalletCoin(walletId));
      return await ref
          .watch(priceAnd24hChangeNotifierProvider)
          .getHistory(coin, 1);
    });

class WalletSummaryInfo extends ConsumerWidget {
  const WalletSummaryInfo({
    super.key,
    required this.walletId,
    required this.initialSyncStatus,
  });

  final String walletId;
  final WalletSyncStatus initialSyncStatus;

  void showSheet(BuildContext context) {
    showModalBottomSheet<dynamic>(
      backgroundColor: Colors.transparent,
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (_) => WalletBalanceToggleSheet(walletId: walletId),
    );
  }

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    debugPrint("BUILD: $runtimeType");

    final coin = ref.watch(pWalletCoin(walletId));
    final balance = ref.watch(pWalletBalance(walletId));

    final locale = ref.watch(
      localeServiceChangeNotifierProvider.select((value) => value.locale),
    );

    final baseCurrency = ref.watch(
      prefsChangeNotifierProvider.select((value) => value.currency),
    );

    // Watched via select so toggling it rebuilds only this block.
    final privacyMode = ref.watch(
      prefsChangeNotifierProvider.select((value) => value.privacyMode),
    );

    ({double change24h, Decimal value})? price;
    if (ref.watch(
      prefsChangeNotifierProvider.select((value) => value.externalCalls),
    )) {
      price = ref.watch(
        priceAnd24hChangeNotifierProvider.select(
          (value) => value.getPrice(coin),
        ),
      );
    }

    final _showAvailable =
        ref.watch(walletBalanceToggleStateProvider) ==
        WalletBalanceToggleState.available;

    final Amount balanceToShow;
    final String title;

    final bool toggleBalance;

    if (coin is Firo || ref.watch(pWalletInfo(walletId)).isMwebEnabled) {
      toggleBalance = false;
      final type = ref.watch(publicPrivateBalanceStateProvider.state).state;
      title =
          "${_showAvailable ? "Available" : "Full"} ${type.name.capitalize()} balance";
      switch (type) {
        case BalanceType.private:
          final balance = coin is Firo
              ? ref.watch(pWalletBalanceTertiary(walletId))
              : ref.watch(pWalletBalanceSecondary(walletId));
          balanceToShow = _showAvailable ? balance.spendable : balance.total;
          break;

        case BalanceType.public:
          final balance = ref.watch(pWalletBalance(walletId));
          balanceToShow = _showAvailable ? balance.spendable : balance.total;
          break;
      }
    } else {
      toggleBalance = true;
      balanceToShow = _showAvailable ? balance.spendable : balance.total;
      title = _showAvailable ? "Available balance" : "Full balance";
    }

    List<int>? imageBytes;

    if (coin is Banano) {
      imageBytes = (ref.watch(pWallets).getWallet(walletId) as BananoWallet)
          .getMonkeyImageBytes();
    }

    // Hero balance: split the formatted amount into a full-weight part and
    // de-emphasized trailing "dust" decimals (locale-safe: the decimal
    // separator is whatever [.,] appears last in the numeric string).
    final formatter = ref.watch(pAmountFormatter(coin));
    final String fullStr = formatter.format(balanceToShow);
    final String numStr = formatter.format(balanceToShow, withUnitName: false);
    final String unitStr = fullStr.startsWith(numStr)
        ? fullStr.substring(numStr.length).trim()
        : coin.ticker;
    // The break is AT the decimal separator, so the headline is the whole
    // coins and everything under one coin is the quiet part — 87,432 then
    // .19045008. It used to keep the first two decimals at full size, which
    // read as a currency's cents on a coin that has eight decimal places and
    // no cents, and left the separator stranded in the large text.
    String mainPart = numStr;
    String dustPart = "";
    final sepIdx = numStr.lastIndexOf(RegExp(r"[.,]"));
    if (sepIdx > 0 && numStr.length - sepIdx - 1 > 3) {
      mainPart = numStr.substring(0, sepIdx);
      dustPart = numStr.substring(sepIdx);
    }

    // Past a million, show the magnitude rather than every satoshi. The
    // FittedBox below does not clip an over-long balance, it shrinks it, so
    // Pepecoin's ten digit figures were quietly demoting the headline number
    // to something smaller than the line under it. Anything that fits is
    // still shown in full.
    final withoutDust = withoutDustDecimals(numStr);
    if (withoutDust != null) {
      mainPart = withoutDust;
      dustPart = "";
    }

    // Privacy mode: replace the digits entirely rather than blurring or
    // shrinking them. A fixed-width mask also means the hero does not change
    // size when toggled, so it cannot leak the magnitude of the balance
    // through its own layout.
    if (privacyMode) {
      mainPart = "••••••";
      dustPart = "";
    }

    // This block sits on the solid hero, not on the page background, so it
    // needs on-hero ink rather than themed ink. Themed ink would be dark in
    // the light theme, sitting illegibly on a saturated fill — the same trap
    // coin_card.dart documents for BitFinite's colour.
    //
    // It does NOT follow the theme's brightness, but it cannot be hardcoded
    // white either: the hero is the theme's own colour, which is a light
    // orange in some themes where white measures 3.00:1. heroInk derives it
    // from the fill. Every label here is built from favText, so this one value
    // carries the whole block.
    final favText = heroInk(kHeroSurface);
    final colors = Theme.of(context).extension<StackColors>()!;
    final receivingAddress = ref.watch(pWalletReceivingAddress(walletId));
    // Spec: 52px / 700 / letter-spacing -0.02em, tabular. -0.02em at 52px is
    // -1.04, so the previous -1.2 was slightly tighter than intended; w800 was
    // also heavier than the design, which relies on size rather than weight to
    // carry the balance.
    // 30, down again from 36 (which was down from 44, and 52 in the spec).
    // The hero scrolls away now, so it no longer has to earn its height by
    // being the only thing on screen, and the balance still outranks
    // everything under it by more than double — the fiat line is 13.
    // Hierarchy here comes from the gap and the weight, not the absolute
    // size. The -0.02em tracking follows the size: -0.02 x 30.
    final heroStyle = STextStyles.pageTitleH1(context).copyWith(
      fontSize: 30,
      fontWeight: FontWeight.w700,
      height: 1.05,
      letterSpacing: -0.6,
      color: favText,
      fontFeatures: const [FontFeature.tabularFigures()],
    );

    return ConditionalParent(
      condition: imageBytes != null,
      builder: (child) => Stack(
        children: [
          Positioned.fill(
            left: 150.0,
            child: SvgPicture.memory(Uint8List.fromList(imageBytes!)),
          ),
          child,
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                child: GestureDetector(
                  onTap: () {
                    if (toggleBalance) {
                      if (ref.read(walletBalanceToggleStateProvider) ==
                          WalletBalanceToggleState.available) {
                        ref
                                .read(walletBalanceToggleStateProvider.notifier)
                                .state =
                            WalletBalanceToggleState.full;
                      } else {
                        ref
                                .read(walletBalanceToggleStateProvider.notifier)
                                .state =
                            WalletBalanceToggleState.available;
                      }
                    } else {
                      showSheet(context);
                    }
                  },
                  child: Row(
                    children: [
                      Flexible(
                        child: Text(
                          title.toUpperCase(),
                          overflow: TextOverflow.ellipsis,
                          // Spec: 12px / 600 / 0.1em tracking (= 1.2 at 12px).
                          //
                          // Opacity deliberately stays at 0.80 rather than the
                          // spec's 0.72: measured on blue-600, 0.72 gives
                          // 4.19:1 and 0.76 gives 4.49:1 — both under the 4.5:1
                          // AA floor for text this size. 0.80 is the first
                          // passing step at 4.84:1. The design's intent is a
                          // de-emphasised label, and 0.80 still reads as one;
                          // shipping 0.72 would just be an unreadable one.
                          style: STextStyles.subtitle500(context).copyWith(
                            fontSize: 12,
                            fontWeight: FontWeight.w600,
                            letterSpacing: 1.2,
                            color: favText.withOpacity(
                              heroEmphasis(favText, 0.8),
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(width: 5),
                      SvgPicture.asset(
                        Assets.svg.chevronDown,
                        color: favText.withOpacity(heroEmphasis(favText, 0.8)),
                        width: 8,
                        height: 4,
                      ),
                    ],
                  ),
                ),
              ),
              const SizedBox(width: 8),
              // Privacy toggle. Sits beside the label it governs rather than in
              // a menu: hiding your balance is something you do *now*, because
              // of who is next to you, so it has to be one tap from the number
              // it hides.
              GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: () {
                  final prefs = ref.read(prefsChangeNotifierProvider);
                  prefs.privacyMode = !prefs.privacyMode;
                },
                child: Padding(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 6,
                    vertical: 4,
                  ),
                  child: SvgPicture.asset(
                    privacyMode ? Assets.svg.eyeSlash : Assets.svg.eye,
                    // Same ink as the label; on the hero everything derives
                    // from the hero, never from the page theme.
                    color: favText.withOpacity(heroEmphasis(favText, 0.8)),
                    width: 18,
                    height: 18,
                  ),
                ),
              ),
              const SizedBox(width: 4),
              WalletSyncChip(
                walletId: walletId,
                initialSyncStatus: initialSyncStatus,
              ),
            ],
          ),
          const SizedBox(height: 10),
          // "(View only)" used to sit here; the redesign moves that fact to
          // the app bar as the wallet's account-type subtitle (WATCH ONLY),
          // where it labels the wallet rather than interrupting the balance.
          GestureDetector(
            behavior: HitTestBehavior.opaque,
            // Tap the balance to change how many decimals are shown, per coin
            // (Settings > Advanced > Manage coin units). Nothing is hardcoded.
            onTap: () => Navigator.of(
              context,
            ).pushNamed(EditCoinUnitsView.routeName, arguments: coin),
            child: FittedBox(
              fit: BoxFit.scaleDown,
              child: Text.rich(
                TextSpan(
                  children: [
                    TextSpan(text: mainPart, style: heroStyle),
                    if (dustPart.isNotEmpty)
                      TextSpan(
                        text: dustPart,
                        style: heroStyle.copyWith(
                          fontSize: 15,
                          fontWeight: FontWeight.w700,
                          // 0.4 measured 2.21:1 on blue-600 — under even the
                          // 3:1 large-text floor, and these are real satoshi
                          // digits of the balance, not decoration. 0.62 gives
                          // 3.46:1 and still reads as secondary against the
                          // 52px full-opacity main part.
                          color: favText.withOpacity(
                            heroEmphasis(favText, 0.62),
                          ),
                        ),
                      ),
                    TextSpan(
                      text: " $unitStr",
                      style: heroStyle.copyWith(
                        fontSize: 14,
                        fontWeight: FontWeight.w700,
                        color: favText.withOpacity(heroEmphasis(favText, 0.85)),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
          // Fiat sits directly under the balance it converts, above the address:
          // the two are the same quantity in two units, and putting an unrelated
          // chip between them made the second read as a third number. Quieter
          // than the balance — it restates it rather than adding a fact.
          //
          // No "≈" in front. It was there because the figure genuinely is
          // approximate, being a cached market price against a balance, but a
          // symbol most people never type is a poor way to say so, and it
          // sits where the eye lands first. The word "today" beside it and
          // the moving price above already read as an estimate.
          if (price != null && price.value > Decimal.zero)
            Padding(
              padding: const EdgeInsets.only(top: 4, bottom: 2),
              child: Builder(
                builder: (context) {
                  final fiatNow = price!.value * balanceToShow.decimal;
                  final fiatStr =
                      "${fiatNow.toAmount(fractionDigits: 8).fiatString(locale: locale)} $baseCurrency";

                  // "today" = the 24h change of the HOLDING's fiat value:
                  // balance x (price_now - price_24h_ago), derived from the
                  // same change24h the price rows use, so the two cannot
                  // disagree.
                  String todayStr = "";
                  bool todayDown = false;
                  final c = price.change24h;
                  if (c.isFinite && (100 + c).abs() > 0.001) {
                    final delta = fiatNow.toDouble() * c / (100 + c);
                    todayDown = delta < 0;
                    final sign = todayDown ? "-" : "+";
                    final deltaStr = Decimal.parse(
                      delta.abs().toStringAsFixed(8),
                    ).toAmount(fractionDigits: 8).fiatString(locale: locale);
                    todayStr = "$sign$deltaStr $baseCurrency today";
                  }

                  final base = STextStyles.subtitle500(context).copyWith(
                    color: favText.withOpacity(heroEmphasis(favText, 0.78)),
                    fontSize: 13,
                  );

                  // Masked too: hiding the BFX figure while showing its fiat
                  // value would defeat the point entirely.
                  if (privacyMode) {
                    return Text("•••• $baseCurrency", style: base);
                  }

                  // Only the delta takes the colour. The fiat figure beside it
                  // is the balance restated, not a movement, and colouring it
                  // would claim the whole holding had gone up.
                  //
                  // The sign is still there: colour alone is not a way to say
                  // "down" to a reader who cannot tell these two hues apart.
                  return Text.rich(
                    TextSpan(
                      style: base,
                      children: [
                        TextSpan(text: fiatStr),
                        if (todayStr.isNotEmpty) ...[
                          const TextSpan(text: "  ·  "),
                          TextSpan(
                            text: todayStr,
                            style: base.copyWith(
                              color: onHeroSignal(
                                todayDown
                                    ? colors.accentColorRed
                                    : colors.accentColorGreen,
                              ),
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                        ],
                      ],
                    ),
                  );
                },
              ),
            ),
          if (receivingAddress.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 10),
              child: GestureDetector(
                onTap: () {
                  unawaited(HapticFeedback.lightImpact());
                  Clipboard.setData(ClipboardData(text: receivingAddress));
                  unawaited(
                    showFloatingFlushBar(
                      type: FlushBarType.info,
                      message: "Address copied to clipboard",
                      iconAsset: Assets.svg.copy,
                      context: context,
                    ),
                  );
                },
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    // Derived from the hero ink, NOT from the page theme.
                    // textFieldDefaultBG is a *page* surface colour: near-white
                    // in the light and forest themes, which put white text on
                    // white and made the address unreadable in two themes out
                    // of three. A translucent white scrim works on any hero
                    // colour — today's blue, forest's teal, whatever a future
                    // coin colour brings — because it is the same white the
                    // text already uses, just quieter.
                    // Redesign spec values: rgba(255,255,255,0.12) fill,
                    // 0.22 border, 12px radius. These are tuned for blue-600
                    // #0644F1 — on the old #2F6BFF they would fail AA, which
                    // is why the coin colour moved to blue-600 alongside this.
                    color: favText.withOpacity(0.12),
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(
                      color: favText.withOpacity(0.22),
                      width: 1,
                    ),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        receivingAddress.length > 22
                            ? "${receivingAddress.substring(0, 12)}…"
                                  "${receivingAddress.substring(receivingAddress.length - 6)}"
                            : receivingAddress,
                        style: STextStyles.subtitle500(context).copyWith(
                          // Spec: 13px monospace at 0.92. On blue-600 that is
                          // 5.94:1 — comfortably AA. The same 0.92 on the old
                          // #2F6BFF was 4.05:1 and failed.
                          fontSize: 13,
                          color: favText.withOpacity(
                            heroEmphasis(favText, 0.92),
                          ),
                          fontFeatures: const [FontFeature.tabularFigures()],
                        ),
                      ),
                      const SizedBox(width: 8),
                      SvgPicture.asset(
                        Assets.svg.copy,
                        width: 14,
                        height: 14,
                        // The only affordance signalling the chip is tappable,
                        // so it has to be findable rather than decorative.
                        color: favText.withOpacity(heroEmphasis(favText, 0.8)),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          // The market, last and smallest. It used to sit above the balance
          // with its own chart and a range selector, which put the number
          // somebody opened the wallet for in third place behind a line most
          // of them never read. Hidden in privacy mode for the same reason
          // the fiat figure is: the shape still says how it moved.
          if (price != null && price.value > Decimal.zero && !privacyMode)
            _HeroMarketRow(
              walletId: walletId,
              favText: favText,
              price: price,
              locale: locale,
              baseCurrency: baseCurrency,
            ),
        ],
      ),
    );
  }
}

/// The market, as one row at the foot of the hero.
///
/// What a coin costs, how it moved today, the shape of that move, and a way
/// in. Everything else the old card carried — the range selector and a chart
/// large enough to argue with — moved to [PriceView], where a chart has the
/// room to be read and does not compete with the balance for the top of the
/// card.
///
/// Every ink derives from favText so the row follows any coin colour and
/// either ink polarity, the same rule the rest of the hero follows.
class _HeroMarketRow extends ConsumerWidget {
  const _HeroMarketRow({
    required this.walletId,
    required this.favText,
    required this.price,
    required this.locale,
    required this.baseCurrency,
  });

  final String walletId;
  final Color favText;
  final ({double change24h, Decimal value}) price;
  final String locale;
  final String baseCurrency;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final coin = ref.watch(pWalletCoin(walletId));
    final colors = Theme.of(context).extension<StackColors>()!;

    // The glyph only. Its absence costs the row nothing: the price and the
    // change are worth showing on their own, and a coin whose series has not
    // arrived should not hold them back.
    final series = ref
        .watch(_heroMarketProvider(walletId))
        .asData
        ?.value
        ?.series;

    final c = price.change24h;
    final down = c < 0;
    final changeStr = c.isFinite
        ? "${down ? "-" : "+"}${c.abs().toStringAsFixed(2)}% 24h"
        : "";
    final signal = onHeroSignal(
      down ? colors.accentColorRed : colors.accentColorGreen,
    );

    // The same formatter the price screen uses. A card that says 0.04 and a
    // screen that says 0.04320 for the same coin read as one of them being
    // out of date.
    final priceStr = priceFigure(price.value.toDouble(), locale, baseCurrency);

    return Padding(
      padding: const EdgeInsets.only(top: 14),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // A rule, because what follows is a different subject rather than
          // another line about the balance.
          Container(height: 1, color: favText.withOpacity(0.16)),
          GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () => Navigator.of(
              context,
            ).pushNamed(PriceView.routeName, arguments: coin),
            child: Padding(
              padding: const EdgeInsets.only(top: 12, bottom: 2),
              child: Row(
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          "${coin.ticker.toUpperCase()} PRICE",
                          style: STextStyles.subtitle500(context).copyWith(
                            fontSize: 10,
                            fontWeight: FontWeight.w600,
                            letterSpacing: 1.0,
                            color: favText.withOpacity(
                              heroEmphasis(favText, 0.8),
                            ),
                          ),
                        ),
                        const SizedBox(height: 3),
                        Row(
                          crossAxisAlignment: CrossAxisAlignment.baseline,
                          textBaseline: TextBaseline.alphabetic,
                          children: [
                            Flexible(
                              // Shrinks rather than truncates. An ellipsised
                              // price is itself a plausible price, and this
                              // row has to hold both eight decimals of a coin
                              // trading under a cent and five figures of one
                              // that is not.
                              child: FittedBox(
                                fit: BoxFit.scaleDown,
                                alignment: Alignment.centerLeft,
                                child: Text(
                                  priceStr,
                                  maxLines: 1,
                                  style: STextStyles.subtitle500(context)
                                      .copyWith(
                                        fontSize: 13,
                                        fontWeight: FontWeight.w700,
                                        color: favText.withOpacity(
                                          heroEmphasis(favText, 0.92),
                                        ),
                                        fontFeatures: const [
                                          FontFeature.tabularFigures(),
                                        ],
                                      ),
                                ),
                              ),
                            ),
                            if (changeStr.isNotEmpty) ...[
                              const SizedBox(width: 8),
                              // Labelled "24h". An unlabelled percentage on a
                              // card that also carries a holding's daily
                              // change is two different claims wearing one
                              // shape.
                              Text(
                                changeStr,
                                style: STextStyles.subtitle500(context)
                                    .copyWith(
                                      fontSize: 12,
                                      fontWeight: FontWeight.w600,
                                      color: signal,
                                      fontFeatures: const [
                                        FontFeature.tabularFigures(),
                                      ],
                                    ),
                              ),
                            ],
                          ],
                        ),
                      ],
                    ),
                  ),
                  if (series != null && series.length > 1) ...[
                    const SizedBox(width: 12),
                    SizedBox(
                      width: 64,
                      child: MiniSparkline(
                        series: series,
                        color: signal,
                        height: 26,
                      ),
                    ),
                  ],
                  const SizedBox(width: 6),
                  SvgPicture.asset(
                    Assets.svg.chevronRight,
                    width: 12,
                    height: 12,
                    color: favText.withOpacity(heroEmphasis(favText, 0.8)),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}
